import React, { useState } from 'react';
import { 
  Trash2, Map, Calendar, Star, LineChart, Users, 
  HardHat, FileText, Activity, ShieldAlert, ChevronLeft 
} from 'lucide-react';

const Dashboard = () => {
  const [currentView, setCurrentView] = useState('MENU');

  const allTabs = [
    { id: 'BINS', label: '01_BIN_MONITORING', icon: <Trash2 size={28}/> },
    { id: 'ZONES', label: '02_AREAS_&_ZONES', icon: <Map size={28}/> },
    { id: 'SCHEDULE', label: '03_COLL_SCHEDULE', icon: <Calendar size={28}/> },
    { id: 'POINTS', label: '04_REWARDS_POINTS', icon: <Star size={28}/> },
    { id: 'ANALYTICS', label: '05_SYS_ANALYTICS', icon: <LineChart size={28}/> },
    { id: 'CITIZENS', label: '06_CITIZEN_INFO', icon: <Users size={28}/> },
    { id: 'WORKERS', label: '07_WORKER_NODES', icon: <HardHat size={28}/> },
    { id: 'REPORTS', label: '08_SYS_REPORTS', icon: <FileText size={28}/> },
  ];

  return (
    <div className="w-full min-h-screen bg-[#FDFAD8] p-6 md:p-12 lg:p-16 flex flex-col items-center font-sans overflow-x-hidden">

      {/* THE HEADER: Slimmer and wider to open up the top */}
      <div className="w-full max-w-[1200px] bg-[#AB1717] border-[6px] border-[#47510B] rounded-t-[40px] rounded-b-[15px] p-6 md:p-8 red-stack-shadow mb-10 shrink-0">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-6">
            <div className="bg-[#FDFAD8] p-3 rounded-2xl border-4 border-[#47510B] shadow-[4px_4px_0_0_#47510B]">
              <ShieldAlert size={32} className="text-[#AB1717]" strokeWidth={2.5} />
            </div>
            <div>
              <p className="text-[10px] font-black uppercase tracking-[0.5em] text-[#FDFAD8] opacity-60 italic mb-1">Command.Master.Console</p>
              <h1 className="text-3xl md:text-5xl font-black italic text-[#FDFAD8] uppercase tracking-tighter leading-none">
                TRASH<span className="text-[#CAD23C]">2</span>TRACK
              </h1>
            </div>
          </div>
          <div className="hidden sm:flex flex-col items-end">
            <Activity className="text-[#CAD23C] animate-pulse" size={32} />
            <span className="text-[9px] font-black text-[#FDFAD8] opacity-40 uppercase tracking-widest mt-2">V3.0_STABLE</span>
          </div>
        </div>
      </div>

      {/* THE DYNAMIC CONTENT AREA */}
      <div className="w-full max-w-[1200px] flex-grow">
        {currentView === 'MENU' ? (
          /* THE BUTTON GRID: Increased gaps and padding to stop the "suffocating" feel */
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8 md:gap-10 animate-slot">
            {allTabs.map((tab) => (
              <button
                key={tab.id}
                onClick={() => setCurrentView(tab.id)}
                className="group relative flex flex-col items-center justify-center aspect-square md:aspect-[4/3] p-8 rounded-[35px] border-[6px] border-[#47510B] bg-[#A1AED1] transition-all duration-300 hover:-translate-y-2 hover:bg-[#CAD23C] shadow-[0_12px_0_0_#47510B] hover:shadow-[0_4px_0_0_#47510B]"
              >
                {/* Visual "Groove" behind the icon */}
                <div className="mb-4 p-4 rounded-full bg-[#FDFAD8] border-4 border-[#47510B] group-hover:bg-[#47510B] group-hover:text-[#CAD23C] text-[#AB1717] transition-colors">
                  {tab.icon}
                </div>

                <span className="text-xs md:text-sm font-black uppercase tracking-tighter text-[#47510B] text-center leading-tight px-2">
                  {tab.label.replace(/_/g, ' ')}
                </span>

                {/* Status dot */}
                <div className="absolute top-4 right-6 w-2 h-2 rounded-full bg-[#47510B] group-hover:bg-[#AB1717] animate-pulse" />
              </button>
            ))}
          </div>
        ) : (
          /* THE DETAIL VIEW: High contrast and wide open space */
          <div className="animate-slot flex flex-col items-center gap-8">
            <button 
              onClick={() => setCurrentView('MENU')}
              className="group flex items-center gap-3 bg-[#47510B] text-[#FDFAD8] px-10 py-4 rounded-full font-black uppercase text-xs transition-all hover:bg-[#AB1717] shadow-[6px_6px_0_0_#A1AED1] active:translate-y-1"
            >
              <ChevronLeft size={20} /> Return_to_Console
            </button>

            <div className="w-full bg-white border-[8px] border-[#47510B] rounded-[50px] p-12 md:p-24 text-center shadow-2xl min-h-[500px] flex flex-col items-center justify-center">
              <h2 className="text-5xl md:text-7xl font-black italic text-[#47510B] uppercase tracking-tighter mb-6">
                {currentView} <span className="text-[#AB1717]">_NODE</span>
              </h2>
              <div className="w-32 h-2 bg-[#CAD23C] rounded-full mb-8" />
              <p className="font-bold text-[#A1AED1] tracking-[1em] uppercase text-[10px]">Awaiting_Command_Line</p>
            </div>
          </div>
        )}
      </div>

      {/* FOOTER: Pushed to the very bottom with a thin line */}
      <div className="w-full max-w-[1200px] mt-12 pt-8 border-t-4 border-[#47510B]/10 flex flex-col items-center opacity-40">
        <p className="text-[10px] font-black uppercase tracking-[1.5em] text-[#47510B] text-center">
          Trash2Track.Industrial.OS
        </p>
      </div>
    </div>
  );
};

export default Dashboard;
